script:
// Tengelykapcsoló gumibetéttel – 3D nézet / Shaft coupling with rubber elements – 3D view
// Két karima között gumielemek viszik át a nyomatékot. Tengelyszög-hiba (α) és pozícióhiba (e) esetén minden elem fordulatonként nyúlik és nyomódik.
// Rubber elements between two flanges carry the torque. With an angle error α and a position error e, each element stretches and compresses once per turn.
// Modell / model: a hajtó oldal a motor (a fordulatszámot tartja); a hajtott oldal J tehetetlenségű; a gumi csavarórugóként (k_t) és csillapításként (c) hat. A gumielemek hossza a két karima geometriájából adódik.
// Model: the motor side holds the speed; the driven side has inertia J; the rubber acts as a torsional spring (k_t) with damping (c). Each element's length follows from the flange geometry.
// 3D tengelyek: x a tengely irányában, y felfelé, z a néző felé / 3D axes: x along the shaft, y up, z towards the viewer

// Vászon és felirat / Canvas and caption
stage(1000, 600, "#fbfbf8");
title({hu: "Tengelykapcsoló gumibetéttel", en: "Shaft coupling with rubber elements"});
// Kezdő lassítás (a Sebesség csúszkán állítható) / Initial slow motion (adjustable on the Speed slider)
timeScale(0.5);
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(4);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("n",     {hu: "Fordulatszám n", en: "Speed n"}, 0, 300, 120, 5, "1/min");
param("T",     {hu: "Terhelő nyomaték T", en: "Load torque T"}, 0, 150, 80, 1, "N·m");
param("alpha", {hu: "Tengelyszög-hiba α", en: "Shaft angle error α"}, -5, 5, 2, 0.1, "°");
param("e",     {hu: "Tengelypozíció-hiba e (párhuzamos eltolás)", en: "Shaft position error e (parallel offset)"}, -10, 10, 3, 0.5, "mm");
param("kt",    {hu: "Gumi csavarómerevsége k_t", en: "Rubber torsional stiffness k_t"}, 200, 3000, 1000, 50, "N·m/rad");
param("J",     {hu: "Hajtott oldal tehetetlensége J", en: "Driven-side inertia J"}, 0.1, 2, 0.5, 0.05, "kg·m²");
param("c",     {hu: "Gumi csillapítása c", en: "Rubber damping c"}, 0, 60, 15, 1, "N·m·s/rad");
// Kapcsoló: értéke true / false / Switch: its value is true / false
toggle("big", {hu: "Ábra nagyítása ×3 (α és e)", en: "Zoom the drawing ×3 (α and e)"}, true);
param("yaw",   {hu: "Nézet: elforgatás", en: "View: turn"}, -90, 90, -30, 1, "°");
param("pitch", {hu: "Nézet: dőlés", en: "View: tilt"}, -30, 70, 20, 1, "°");

// Méretek (cm) / Dimensions (cm)
const LG = 6;        // a karimák homlokfelülete közti hézag / gap between the flange faces (cm)
const RF = 8;        // karima sugara / flange radius (cm)
const RP = 5.5;      // a gumielemek csavarköre / pitch circle of the rubber elements (cm)
const NP = 6;        // gumielemek száma / number of rubber elements
const EXT = 12;      // tengelyvég a karima mögött / shaft length behind the flange (cm)

// Állapotváltozók (rad, rad/s, N·m) / State variables (rad, rad/s, N·m)
let f1 = 0, w1 = 0;      // hajtó tengely szöge és szögsebessége / driving shaft angle and speed
let f2 = 0, w2 = 0;      // hajtott tengely szöge és szögsebessége / driven shaft angle and speed
let Tr = 0;              // a gumin átvitt nyomaték / torque through the rubber
let started = false;     // kezdőállapot beállítva / start state set

// Pont egy körön: c középpont, u és v a kör síkjának egységvektorai, r sugár, a szög / Point on a circle: centre c, unit vectors u and v in its plane, radius r, angle a
function onDisc(c, u, v, r, a) {
  return [0, 1, 2].map(k => c[k] + r * (cos(a) * u[k] + sin(a) * v[k]));
}

// A karimák és a gumielemek geometriája / Geometry of the flanges and rubber elements
// alpha: tengelyszög (rad), eCm: pozícióhiba (cm), twist: csavarodás φ₁ − φ₂ (rad), ang1: a hajtó tengely szöge φ₁ (rad)
function geo(alpha, eCm, twist, ang1) {
  const ca = cos(alpha), sa = sin(alpha);
  const P1 = [-LG / 2, 0, 0];                       // hajtó karima középpontja / driving flange centre
  const P2 = [LG / 2 * ca, LG / 2 * sa + eCm, 0];   // hajtott karima középpontja (megdőlve, eltolva) / driven flange centre (tilted, offset)
  const u1 = [0, 1, 0], v1 = [0, 0, 1];             // hajtó karima síkja / driving flange plane
  const u2 = [-sa, ca, 0], v2 = [0, 0, 1];          // hajtott karima síkja / driven flange plane
  const a2 = [ca, sa, 0];                           // hajtott tengely iránya / driven shaft direction
  const pins = [];
  for (let i = 0; i < NP; i++) {
    const a = ang1 + 2 * PI * i / NP;               // az i-edik furat szöge a hajtó karimán / angle of hole i on the driving flange
    const b = a - twist;                            // ugyanez a furat a hajtott karimán, a csavarodás miatt hátrébb / the same hole on the driven flange, behind by the twist
    const A = onDisc(P1, u1, v1, RP, a);
    const B = onDisc(P2, u2, v2, RP, b);
    const dx = B[0] - A[0], dy = B[1] - A[1], dz = B[2] - A[2];
    const ax = dx;                                  // tengelyirányú hossz (cm): ez nyúlik / axial length (cm): this is what stretches
    const lat = sqrt(dy * dy + dz * dz);            // oldalirányú elmozdulás a két vége között (nyírás) / lateral offset between its two ends (shear)
    pins.push({A, B, ax, tilt: atan2(lat, dx)});    // tilt: az elem dőlése a tengelyhez képest / tilt of the element relative to the axis
  }
  return {P1, P2, u1, v1, u2, v2, a2, pins};
}

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in small steps, dt is the step length (s)
update(dt => {
  if (!started) {
    // Induló állapot: a gumi már a terhelő nyomatékkal csavarodott / start state: the rubber is already twisted by the load torque
    started = true;
    f2 = f1 - P.T / P.kt;
    w2 = w1;
  }
  const wSet = P.n * 2 * PI / 60;     // beállított szögsebesség (rad/s) / set speed (rad/s)
  const h = dt / 2;                   // két részlépés / two sub-steps
  for (let k = 0; k < 2; k++) {
    // Motor: a beállított fordulatszámot kb. 0,3 s alatt éri el / the motor reaches the set speed in about 0.3 s
    w1 += (wSet - w1) * min(1, h / 0.3);
    // Gumi nyomatéka: csavarórugó + csillapítás, ugyanabban a pillanatban mért szögekkel / rubber torque: torsional spring + damping, from the angles at the same instant
    Tr = P.kt * (f1 - f2) + P.c * (w1 - w2);
    // Hajtott oldal: J·dω/dt = a gumi nyomatéka − terhelő nyomaték / driven side: J·dω/dt = rubber torque − load torque
    w2 += (Tr - P.T) / P.J * h;
    f2 += w2 * h;
    f1 += w1 * h;                       // a hajtó szög csak a nyomaték számítása után változik / the driving angle changes only after the torque is computed
  }
});

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  const VX = P.big ? 3 : 1;                                        // ábra-nagyítás / drawing zoom
  const gd = geo(deg(P.alpha) * VX, P.e / 10 * VX, f1 - f2, f1);   // rajzolt geometria / drawn geometry
  const gr = geo(deg(P.alpha), P.e / 10, f1 - f2, f1);             // valódi geometria a mérésekhez / true geometry for the readouts

  // 3D nézet: középpont, lépték (px/cm), elforgatás, dőlés / 3D view: centre, scale (px per cm), turn, tilt
  view3d({x: 500, y: 300, scale: 14, yaw: deg(P.yaw), pitch: deg(P.pitch), dist: 0});
  // Innentől a 3D elemek mélység szerint rendeződnek / From here, 3D items are depth-sorted
  begin3();

  // Hajtó tengely és karima / driving shaft and flange
  wire3([[gd.P1[0] - EXT, 0, 0], gd.P1], {color: "#7d8796", lw: 14});
  face3(circle3(gd.P1, "x", RF, 48), {fill: "#cfd6e0", stroke: "#6b7480", lw: 1.5});
  wire3(circle3(gd.P1, "x", RF, 48), {color: "#5f6875", lw: 2}, true);

  // Hajtott tengely és karima, a tengelyszög-hibával megdőlve / driven shaft and flange, tilted by the angle error
  const end2 = [gd.P2[0] + EXT * gd.a2[0], gd.P2[1] + EXT * gd.a2[1], 0];
  wire3([gd.P2, end2], {color: "#7d8796", lw: 14});
  face3(circle3(gd.P2, gd.a2, RF, 48), {fill: "#dde3ec", stroke: "#6b7480", lw: 1.5});
  wire3(circle3(gd.P2, gd.a2, RF, 48), {color: "#5f6875", lw: 2}, true);

  // Gumielemek: nyúlt (narancs) vagy összenyomott (kék) / Rubber elements: stretched (orange) or compressed (blue)
  for (const p of gd.pins) {
    const s = p.ax - LG;                                           // nyúlás (cm) / stretch (cm)
    const col = s > 0.01 ? "#e0802b" : (s < -0.01 ? "#2f80c8" : "#3b3b3b");
    wire3([p.A, p.B], {color: col, lw: 11});
    wire3(circle3(p.A, "x", 1.1, 16), {color: "#222", lw: 2}, true);      // csavarfej / bolt head
    wire3(circle3(p.B, gd.a2, 1.1, 16), {color: "#222", lw: 2}, true);
  }

  // Forgásjelölők: piros a hajtó, kék a hajtott karimán / rotation markers: red on the driving, blue on the driven flange
  wire3([gd.P1, onDisc(gd.P1, gd.u1, gd.v1, RF * 0.9, f1)], {color: C.red, lw: 4});
  wire3([gd.P2, onDisc(gd.P2, gd.u2, gd.v2, RF * 0.9, f2)], {color: C.blue, lw: 4});
  // A 3D elemek kirajzolása (a távoliak előbb) / Draw the 3D items (far ones first)
  end3();

  // Feliratok és jelmagyarázat a vásznon / Labels and legend on the canvas
  const q1 = p3([gd.P1[0] - EXT, 0, 0]);
  const q2 = p3(end2);
  const mid = [0, 1, 2].map(k => (gd.pins[0].A[k] + gd.pins[0].B[k]) / 2);
  const qm = p3(mid);
  text({hu: "hajtó tengely (motor)", en: "driving shaft (motor)"}, q1[0], q1[1] - 22, {size: 14, align: "center"});
  text({hu: "hajtott tengely (terhelés)", en: "driven shaft (load)"}, q2[0], q2[1] - 22, {size: 14, align: "center"});
  text({hu: "gumielem", en: "rubber element"}, qm[0] + 14, qm[1] - 14, {size: 13, color: C.gray});
  text({hu: "Gumielemek: narancs = nyúlt, kék = összenyomott · piros / kék jel = a karimák elfordulása", en: "Rubber elements: orange = stretched, blue = compressed · red / blue marker = flange turn"}, 22, 530, {size: 13, color: C.ink});
  if (P.big) text({hu: "Ábra: α és e ×3-szorosra nagyítva; a mért értékek valódiak", en: "Drawing: α and e magnified ×3; the readouts are true values"}, 22, 552, {size: 13, color: C.gray});

  // Mért értékek a Vezérlők fülön (valódi értékek) / Readouts on the Controls tab (true values)
  const twistDeg = todeg(wrap(f1 - f2));
  const dL = gr.pins.map(p => (p.ax - LG) * 10);                   // nyúlás mm-ben / stretch in mm
  const dLmax = dL.reduce((a, b) => max(a, b), -1e9);
  const dLmin = dL.reduce((a, b) => min(a, b), 1e9);
  const tiltMax = todeg(gr.pins.reduce((a, p) => max(a, p.tilt), 0));
  show({hu: "Hajtó fordulatszám n₁", en: "Driving speed n₁"}, w1 * 60 / (2 * PI), "1/min", 1);
  show({hu: "Hajtott fordulatszám n₂", en: "Driven speed n₂"}, w2 * 60 / (2 * PI), "1/min", 1);
  show({hu: "Átvitt nyomaték M", en: "Transmitted torque M"}, Tr, "N·m", 1);
  show({hu: "Terhelő nyomaték T", en: "Load torque T"}, P.T, "N·m", 1);
  show({hu: "Csavarodás φ₁ − φ₂", en: "Twist φ₁ − φ₂"}, twistDeg, "°", 2);
  show({hu: "Egyensúlyi csavarodás T / k_t", en: "Steady-state twist T / k_t"}, todeg(P.T / P.kt), "°", 2);
  show({hu: "Gumi sajátfrekvenciája f₀ = √(k_t / J) / 2π", en: "Rubber natural frequency f₀ = √(k_t / J) / 2π"}, sqrt(P.kt / P.J) / (2 * PI), "Hz", 2);
  show({hu: "Gumielem legnagyobb nyúlása", en: "Largest stretch of an element"}, dLmax, "mm", 2);
  show({hu: "Gumielem legnagyobb összenyomódása", en: "Largest compression of an element"}, dLmin, "mm", 2);
  show({hu: "Gumielem legnagyobb dőlése (nyírás)", en: "Largest tilt of an element (shear)"}, tiltMax, "°", 2);
  show({hu: "Párhuzamos eltolás e", en: "Parallel offset e"}, P.e, "mm", 1);
  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "Átvitt nyomaték M", en: "Transmitted torque M"}, Tr, {unit: "N·m", color: C.blue, group: "M"});
  plot({hu: "Csavarodás", en: "Twist"}, twistDeg, {unit: "°", color: C.orange, group: "szog"});
  plot({hu: "Gumielem nyúlása (max.)", en: "Element stretch (max.)"}, dLmax, {unit: "mm", color: "#e0802b", group: "nyulas"});
  plot({hu: "Gumielem összenyomódása (max.)", en: "Element compression (max.)"}, dLmin, {unit: "mm", color: "#2f80c8", group: "nyulas"});
});
